def _as_bool(value: Any) -> bool:
    return str(value or "").strip().lower() in {"1", "true", "yes", "y", "on"}


def _parse_integer_charge(value: Any, code: str, field: str) -> int:
    raw = str(value or "").strip()
    if not raw:
        raise ValueError(f"{code}: support matrix is missing integer {field}")
    try:
        parsed = float(raw)
    except ValueError as exc:
        raise ValueError(f"{code}: support matrix {field} is not numeric: {raw!r}") from exc
    if not math.isfinite(parsed) or parsed != round(parsed):
        raise ValueError(f"{code}: support matrix {field} must be an integer: {raw!r}")
    return int(round(parsed))


def _atom_name(value: str) -> str:
    return str(value).strip()


def _mapping_rows() -> dict[str, dict[str, Any]]:
    global _MAPPING_CACHE
    if _MAPPING_CACHE is not None:
        return _MAPPING_CACHE
    if not _MAPPING_PATH.is_file():
        raise FileNotFoundError(f"missing generated NCAA mapping: {_MAPPING_PATH}")
    rows: dict[str, dict[str, Any]] = {}
    current: str | None = None
    # The generated YAML is intentionally simple and has JSON objects on one
    # line.  Avoid adding a YAML dependency to the score-only runtime.
    for raw in _MAPPING_PATH.read_text().splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or line in {"residues:", "schema_version: 1"}:
            continue
        if raw.startswith("  ") and not raw.startswith("    ") and line.endswith(":"):
            current = line.strip()[:-1]
            rows[current] = {}
            continue
        if current is None or ":" not in line:
            continue
        key, value = line.strip().split(":", 1)
        value = value.strip()
        if key == "pdb_alias":
            rows[current][key] = value
        elif key == "params":
            rows[current][key] = value
        elif key == "position_scope":
            rows[current][key] = [item.strip() for item in value.strip("[]").split(",") if item.strip()]
        elif key == "atom_rename":
            rows[current][key] = json.loads(value)
        elif key in {"runtime_name", "runtime_pdb_name", "handling"}:
            rows[current][key] = value
    if not rows:
        raise ValueError(f"generated NCAA mapping has no residues: {_MAPPING_PATH}")
    _MAPPING_CACHE = rows
    return rows


